import [printf] from "std/c.bpl";

frame main() ret int {
    # Integer type
    local age: int = 25;           # 32-bit signed integer (most common)

    # Floating point (decimals)
    local price: float = 19.99;    # 64-bit floating point

    # Boolean (true/false)
    local isActive: bool = true;

    # Character (single letter)
    local grade: char = 'A';

    # String (text)
    local greeting: string = "Hello, World!";

    # Print them all!
    printf("Age: %d\n", age);
    printf("Price: %.2f\n", price);
    printf("Is Active: %d\n", isActive);  # 1 = true, 0 = false
    printf("Grade: %c\n", grade);
    printf("Greeting: %s\n", greeting);

    return 0;
}

import [printf] from "std/c.bpl";

frame main() ret int {
    # Variables can be changed (mutated)
    local score: int = 0;
    printf("Initial score: %d\n", score);

    score = 10;  # Assign new value
    printf("After assignment: %d\n", score);

    score = score + 5;  # Add to existing value
    printf("After adding 5: %d\n", score);

    # Shorthand operators
    score = score + 10;   # Same as: score += 10 (if supported)
    printf("Final score: %d\n", score);

    # Constants (cannot be changed)
    local const MAX_SCORE: int = 100;
    printf("Max possible score: %d\n", MAX_SCORE);
    # MAX_SCORE = 200;  # ERROR! Can't modify a const

    return 0;
}

