import [printf] from "std/c.bpl";

frame main() ret int {
    local celsius: float = 25.0;
    local fahrenheit: float = celsius * 9.0 / 5.0 + 32.0;

    printf("%.1f°C = %.1f°F\n", celsius, fahrenheit);

    return 0;
}
